1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "toDisplayName")
23	    @Mapping(target = "initials", source = "owner", qualifiedByName = "toInitials")
24	    @Mapping(target = "membershipNumber", source = "owner", qualifiedByName = "toMembershipNumber")
25	    @Mapping(target = "checkDigit", source = "owner", qualifiedByName = "toCheckDigit")
26	    @Mapping(target = "membershipLevel", source = "owner", qualifiedByName = "toMembershipLevel")
27	    @Mapping(target = "locality", source = "owner", qualifiedByName = "toLocality")
28	    @Mapping(target = "contactPreference", source = "owner", qualifiedByName = "toContactPreference")
29	    @Mapping(target = "identityKey", source = "owner", qualifiedByName = "toIdentityKey")
30	    @Mapping(target = "ageBand", source = "owner", qualifiedByName = "toAgeBand")
31	    OwnerDto toOwnerDto(Owner owner);
32	
33	    /**
34	     * Derives the owner's {@code ageBand} from its {@code birthDate}, computed against the
35	     * {@code registrationDate}: {@code 'MINOR'} when the owner is under 18 on the registration date,
36	     * {@code 'ADULT'} from 18 up to and including 64, and {@code 'SENIOR'} at 65 or over. Returns
37	     * {@code null} when either the birth date or the registration date is absent.
38	     */
39	    @Named("toAgeBand")
40	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
41	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
42	            return null;
43	        }
44	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
45	        if (age < 18) {
46	            return OwnerDto.AgeBandEnum.MINOR;
47	        }
48	        if (age < 65) {
49	            return OwnerDto.AgeBandEnum.ADULT;
50	        }
51	        return OwnerDto.AgeBandEnum.SENIOR;
52	    }
53	
54	    /**
55	     * Derives the owner's duplicate-detection {@code identityKey}: the single key that consolidates
56	     * the former separate telephone, email and household checks. It is the owner's normalized
57	     * telephone, its email (lower-cased and trimmed, or the empty string when absent) and its
58	     * household identifier (or the empty string when absent), joined in that order by {@code '|'}.
59	     * Because the telephone is part of the key, two members of the same household with different
60	     * telephones have different identity keys; only an exact full-key match is a duplicate.
61	     */
62	    @Named("toIdentityKey")
63	    default String toIdentityKey(Owner owner) {
64	        if (owner == null) {
65	            return null;
66	        }
67	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone().trim();
68	        String email = owner.getEmail() == null ? "" : owner.getEmail().trim().toLowerCase(java.util.Locale.ROOT);
69	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
70	        return telephone + "|" + email + "|" + householdId;
71	    }
72	
73	    /**
74	     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when the owner has a non-blank
75	     * email, otherwise {@code 'PHONE'}.
76	     */
77	    @Named("toContactPreference")
78	    default String toContactPreference(Owner owner) {
79	        if (owner == null) {
80	            return null;
81	        }
82	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
83	        return hasEmail ? "EMAIL" : "PHONE";
84	    }
85	
86	    /**
87	     * Fixed city-to-region table used as the fallback for deriving an owner's locality.
88	     */
89	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
90	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
91	
92	    /**
93	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
94	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Used to derive an
95	     * owner's locality from its postcode in preference to its city.
96	     */
97	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
98	        "NSW", new int[] {2000, 2099},
99	        "VIC", new int[] {3000, 3099},
100	        "QLD", new int[] {4000, 4099});
101	
102	    /**
103	     * Derives the owner's canonical region, the {@code REGION} component of its {@code customerCode}.
104	     * The postcode takes precedence: when the owner has a well-formed 4-digit postcode that falls
105	     * within a known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
106	     * 4000-4099}), that region is returned. Otherwise the region is looked up from the fixed
107	     * city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}),
108	     * yielding {@code 'UNKNOWN'} when the city is not in the table. Preferring the postcode returns
109	     * the same region for known cities but disambiguates cities that share a name.
110	     */
111	    default String toRegion(Owner owner) {
112	        if (owner == null) {
113	            return null;
114	        }
115	        String regionByPostcode = regionForPostcode(owner.getPostcode());
116	        if (regionByPostcode != null) {
117	            return regionByPostcode;
118	        }
119	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
120	    }
121	
122	    /**
123	     * Derives the owner's locality as the {@code REGION} component of its region-and-hash
124	     * {@code customerCode} (the prefix before the first {@code '-'}). The locality therefore shares
125	     * the customer code's identity rather than being computed independently. When the customer code
126	     * is absent the region is derived directly from the owner's postcode and city via
127	     * {@link #toRegion(Owner)}.
128	     */
129	    @Named("toLocality")
130	    default String toLocality(Owner owner) {
131	        if (owner == null) {
132	            return null;
133	        }
134	        String customerCode = owner.getCustomerCode();
135	        if (customerCode != null) {
136	            int dash = customerCode.indexOf('-');
137	            if (dash >= 0) {
138	                return customerCode.substring(0, dash);
139	            }
140	        }
141	        return toRegion(owner);
142	    }
143	
144	    /**
145	     * Returns the region whose inclusive postcode range contains the given 4-digit postcode, or
146	     * {@code null} when the postcode is absent, malformed, or in no known range.
147	     */
148	    private static String regionForPostcode(String postcode) {
149	        if (postcode == null || !postcode.matches("\\d{4}")) {
150	            return null;
151	        }
152	        int value = Integer.parseInt(postcode);
153	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
154	            int[] range = entry.getValue();
155	            if (value >= range[0] && value <= range[1]) {
156	                return entry.getKey();
157	            }
158	        }
159	        return null;
160	    }
161	
162	    /**
163	     * Formats the owner's stored names as {@code 'LastName, FirstName'}.
164	     */
165	    @Named("toDisplayName")
166	    default String toDisplayName(Owner owner) {
167	        if (owner == null) {
168	            return null;
169	        }
170	        return owner.getLastName() + ", " + owner.getFirstName();
171	    }
172	
173	    /**
174	     * Returns the owner's initials as the upper-cased first letters of firstName and lastName,
175	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
176	     */
177	    @Named("toInitials")
178	    default String toInitials(Owner owner) {
179	        if (owner == null) {
180	            return null;
181	        }
182	        return initial(owner.getFirstName()) + initial(owner.getLastName());
183	    }
184	
185	    /**
186	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}, where {@code YY} is
187	     * the last two digits of the {@code registrationDate} year, e.g. {@code 'NSW-1A2B3C4D-M26'}. Returns
188	     * {@code null} when either the customer code or the registration date is absent.
189	     */
190	    @Named("toMembershipNumber")
191	    default String toMembershipNumber(Owner owner) {
192	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
193	            return null;
194	        }
195	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
196	    }
197	
198	    /**
199	     * Returns the owner's numeric membership level, assigned on creation: starts at {@code 1}, plus
200	     * {@code 1} when a non-blank email is present, plus {@code 1} when the owner has no namesakes
201	     * ({@code namesakeCount} is 0), capped at {@code 3} (level 4 is reserved for tenure).
202	     */
203	    @Named("toMembershipLevel")
204	    default Integer toMembershipLevel(Owner owner) {
205	        if (owner == null) {
206	            return null;
207	        }
208	        int level = 1;
209	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
210	        if (hasEmail) {
211	            level++;
212	        }
213	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
214	        if (noNamesakes) {
215	            level++;
216	        }
217	        return Math.min(level, 3);
218	    }
219	
220	    /**
221	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
222	     * contained in the owner's {@code customerCode}. Returns {@code null} when the customer code is
223	     * absent.
224	     */
225	    @Named("toCheckDigit")
226	    default Integer toCheckDigit(Owner owner) {
227	        if (owner == null || owner.getCustomerCode() == null) {
228	            return null;
229	        }
230	        int sum = 0;
231	        boolean dbl = true;
232	        String code = owner.getCustomerCode();
233	        for (int i = code.length() - 1; i >= 0; i--) {
234	            char c = code.charAt(i);
