328	    /**
329	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
330	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
331	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
332	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
333	     * {@code "+61412345678"}.
334	     *
335	     * @param telephone the raw telephone value from the request
336	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
337	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
338	     */
339	    private static String normalizeTelephone(String telephone) {
340	        String e164 = toE164(telephone);
341	        if (e164 == null) {
342	            throw new InvalidFieldValueException("telephone",
343	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
344	        }
345	        return e164;
346	    }
347	
348	    /**
349	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
350	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
351	     * owners' stored numbers when detecting duplicates.
352	     */
353	    private static String toE164(String telephone) {
354	        if (telephone == null) {
355	            return null;
356	        }
357	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
358	        String digits;
359	        if (cleaned.startsWith("+")) {
360	            digits = cleaned.substring(1);
361	        } else {
362	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
363	            digits = "61" + national;
364	        }
365	        if (!digits.matches("[0-9]{8,15}")) {
366	            return null;
367	        }
368	        if (!hasValidNationalLength(digits)) {
369	            return null;
370	        }
371	        return "+" + digits;
372	    }
373	
374	    /**
375	     * Checks the national-number length against the country code for the country codes that pin one.
376	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
377	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
378	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
379	     */
380	    private static boolean hasValidNationalLength(String digits) {
381	        if (digits.startsWith("61")) {
382	            return digits.length() - 2 == 9;
383	        }
384	        if (digits.startsWith("1")) {
385	            return digits.length() - 1 == 10;
386	        }
387	        return true;
388	    }
389	
390	    /**
391	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
392	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
